using System;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;
public static class PortLaunchAudit {
 [Serializable] class Report {public string phase,saveName,scope="Independent fixture supplies buildings/fuel/ammunition and completed shell frame. Silo rockets and railgun sails travel and construct via original game ticks; not a manual-placement or full production-chain proof.";public int rocketStart=20,rocketRemaining,sailStart=80,sailRemaining,structureBaseline,structureNow,cellPoints,liveRockets,liveSails;public long tick,power;public bool sawRocket,sawSail,reloadPreserved;public List<string> errors=new List<string>();}
 static Report r;static int layerId,shellId,starIndex;static int[] silos,rails;static DysonSphere S=>GameMain.data.dysonSpheres[starIndex];static PlanetFactory F=>GameMain.localPlanet.factory;public static bool Passed{get;private set;}static string Folder=>Application.persistentDataPath;
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static void Write(string phase){r.phase=phase;r.tick=GameMain.gameTick;if(silos!=null){r.rocketRemaining=0;foreach(int e in silos)r.rocketRemaining+=F.factorySystem.siloPool[F.entityPool[e].siloId].bulletCount;r.sailRemaining=0;foreach(int e in rails)r.sailRemaining+=F.factorySystem.ejectorPool[F.entityPool[e].ejectorId].bulletCount;r.structureNow=S.totalConstructedStructurePoint;var sh=S.layersIdBased[layerId].shellPool[shellId];r.cellPoints=sh.nodecps[sh.nodecps.Length-1];r.liveRockets=S.rocketCursor-1-S.rocketRecycleCursor;r.liveSails=S.swarm.sailCount;r.power=S.energyGenCurrentTick;r.sawRocket|=r.liveRockets>0;r.sawSail|=r.liveSails>0;}File.WriteAllText(Path.Combine(Folder,"launch-audit.json"),JsonUtility.ToJson(r,true));File.AppendAllText(Path.Combine(Folder,"launch-audit.txt"),JsonUtility.ToJson(r)+"\n");}
 static int Build(int proto,Vector3 pos){var item=LDB.items.Select(proto);var p=pos.normalized*(F.planet.data.QueryHeight(pos.normalized)+.2f);var pre=new PrebuildData{protoId=(short)proto,modelIndex=(short)item.ModelIndex,pos=p,rot=Quaternion.FromToRotation(Vector3.up,p.normalized),itemRequired=0};int id=F.AddPrebuildDataWithComponents(pre);F.BuildFinally(GameMain.mainPlayer,id);for(int i=1;i<F.entityCursor;i++)if(F.entityPool[i].id==i&&F.entityPool[i].protoId==proto&&(F.entityPool[i].pos-p).sqrMagnitude<.01f)return i;throw new Exception("Build failed "+proto);}
 static IEnumerator Capture(string name){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();try{File.WriteAllBytes(Path.Combine(Folder,"launch-"+name+".png"),t.EncodeToPNG());}finally{UnityEngine.Object.Destroy(t);}yield return null;}
 static IEnumerator Run(){Passed=false;r=new Report();File.WriteAllText(Path.Combine(Folder,"launch-audit.txt"),r.scope+"\n");Write("setup");starIndex=GameMain.localStar.index;var s=GameMain.data.CreateDysonSphere(starIndex);var l=s.layersSorted[0];layerId=l.id;
  int[] ns=new int[4];float[] xs={-.06f,.06f,.06f,-.06f},ys={-.06f,-.06f,.06f,.06f};for(int i=0;i<4;i++)ns[i]=l.NewDysonNode(0,new Vector3(xs[i],ys[i],1).normalized*l.orbitRadius);for(int i=0;i<4;i++)Check(l.NewDysonFrame(0,ns[i],ns[(i+1)%4],false)>0,"Frame failed");shellId=l.NewDysonShell(0,new List<int>(ns));Check(shellId>0,"Shell failed");foreach(int id in ns){var n=l.nodePool[id];int guard=0;while(n.spReqOrder>0&&guard++<100000){s.OrderConstructSp(n);s.ConstructSp(n);}Check(n.spReqOrder==0,"Frame fixture incomplete");}
  r.structureBaseline=s.totalConstructedStructurePoint;int testNode=l.NewDysonNode(0,Vector3.left*l.orbitRadius);Check(testNode>0,"Rocket target missing");
  ItemProto gen=null,pole=null,silo=null,rail=null;foreach(var it in LDB.items.dataArray){var d=it.prefabDesc;if(d==null)continue;if(d.isPowerGen&&d.fuelMask>0&&!d.gammaRayReceiver&&(gen==null||d.genEnergyPerTick>gen.prefabDesc.genEnergyPerTick))gen=it;if(d.isPowerNode&&!d.isPowerGen&&!d.isAccumulator&&(pole==null||d.powerCoverRadius>pole.prefabDesc.powerCoverRadius))pole=it;if(d.isSilo)silo=it;if(d.isEjector)rail=it;}
  Check(gen!=null&&pole!=null&&silo!=null&&rail!=null,"Missing launcher/power prototypes");var fuels=ItemProto.fuelNeeds[gen.prefabDesc.fuelMask];int fuel=0;foreach(int id in fuels)if(fuel==0||LDB.items.Select(id).HeatValue>LDB.items.Select(fuel).HeatValue)fuel=id;Check(fuel>0,"No generator fuel");File.AppendAllText(Path.Combine(Folder,"launch-audit.txt"),"generator="+gen.ID+" fuel="+fuel+" pole="+pole.ID+" silo="+silo.ID+" rail="+rail.ID+"\n");
  var planet=GameMain.localPlanet;Vector3 sun=(Vector3)(Quaternion.Inverse(planet.runtimeRotation)*(Vector3)(GameMain.localStar.uPosition-planet.uPosition).normalized);var right=Vector3.Cross(sun,Vector3.up).normalized;var up=Vector3.Cross(right,sun).normalized;var generators=new List<int>();rails=new int[4];silos=new int[2];
  for(int i=0;i<4;i++){float a=i*Mathf.PI*.5f;Vector3 n=(sun*.5f+(right*Mathf.Cos(a)+up*Mathf.Sin(a))*.866f).normalized;var p=n*planet.realRadius;var tangent=Vector3.Cross(n,Vector3.up).normalized;generators.Add(Build(gen.ID,p+tangent*10));Build(pole.ID,p+tangent*4);rails[i]=Build(rail.ID,p);F.factorySystem.ejectorPool[F.entityPool[rails[i]].ejectorId].SetOrbit(1);if(i<2)silos[i]=Build(silo.ID,p-tangent*10);}
  yield return new WaitForSecondsRealtime(2);foreach(int e in generators)Check(F.InsertInto(e,0,fuel,5,0,out var unused)==5,"Generator feed failed");foreach(int e in silos){int id=F.entityPool[e].siloId;Check(F.InsertInto(e,0,F.factorySystem.siloPool[id].bulletId,10,0,out var unused)==10,"Rocket feed failed");}foreach(int e in rails){int id=F.entityPool[e].ejectorId;Check(F.InsertInto(e,0,F.factorySystem.ejectorPool[id].bulletId,20,0,out var unused)==20,"Sail feed failed");}Write("running");
  float deadline=Time.realtimeSinceStartup+420;bool cap=false;while(Time.realtimeSinceStartup<deadline){yield return new WaitForSecondsRealtime(1);Write("launching");if(r.sawRocket&&!cap){cap=true;UIRoot.instance.uiGame.OpenDysonEditor();UIRoot.instance.uiGame.dysonEditor.selection.SetViewStar(GameMain.localStar);yield return new WaitForSecondsRealtime(2);yield return Capture("in-flight");UIRoot.instance.uiGame.dysonEditor._Close();yield return null;}if(r.sawRocket&&r.sawSail&&r.structureNow>r.structureBaseline&&r.cellPoints>0)break;}
  Check(r.sawRocket&&r.rocketRemaining<r.rocketStart&&r.structureNow>r.structureBaseline,"Original rocket launch/arrival not observed");Check(r.sawSail&&r.sailRemaining<r.sailStart&&r.cellPoints>0,"Original sail launch/absorption not observed");int sp=r.structureNow,cp=r.cellPoints;r.saveName="PortLaunch-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Check(GameSave.SaveCurrentGame(r.saveName),"Launch save failed");yield return null;DSPGame.StartGame(r.saveName);yield return null;deadline=Time.realtimeSinceStartup+180;while((!GameMain.isRunning||DSPGame.IsMenuDemo||GameMain.localPlanet==null||!GameMain.localPlanet.factoryLoaded)&&Time.realtimeSinceStartup<deadline)yield return new WaitForSecondsRealtime(1);Check(GameMain.isRunning&&!DSPGame.IsMenuDemo&&GameMain.localPlanet!=null&&GameMain.localPlanet.factoryLoaded,"Reload timeout");Write("reloaded");r.reloadPreserved=r.structureNow>=sp&&r.cellPoints>=cp;Check(r.reloadPreserved,"Built points lost");UIRoot.instance.uiGame.OpenDysonEditor();UIRoot.instance.uiGame.dysonEditor.selection.SetViewStar(GameMain.localStar);yield return new WaitForSecondsRealtime(3);yield return Capture("reloaded");UIRoot.instance.uiGame.dysonEditor._Close();yield return null;Passed=true;Write("passed");
 }
 public static IEnumerator SafeRun(){var run=Run();while(true){object next=null;bool more=false;Exception err=null;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception e){err=e;}if(err!=null){r.errors.Add(err.ToString());Write("failed");Debug.LogError("Launch audit: "+err);break;}if(!more)break;yield return next;}((IDisposable)run).Dispose();}
}
